const PORT_SUFFIX = process.env.BUILD !== "production" ? `-${process.env.BUILD}-${process.env.RELEASE}` : "";
const PORT_EXTENSION = `taostats-extension${PORT_SUFFIX}`;
const PORT_CONTENT = `taostats-content${PORT_SUFFIX}`;
const DEBUG = process.env.DEBUG === "true";
const TEST = process.env.NODE_ENV === "test";
const IS_FIREFOX = process.env.BROWSER === "firefox";
const TAOSTATS_API_URL = process.env.TAOSTATS_API_URL;
const ASSET_DISCOVERY_API_URL = "";
const TAOSTATS_WEB_APP_DOMAIN = "taostats.io";
const TAOSTATS_WEB_APP_URL = "https://taostats.io";
const TAOSTATS_WEB_APP_STAKING_URL = "https://dash.taostats.io/stake";
const TAOSTATS_WEB_APP_SWAP_URL = "https://taostats.io/swap";
const SIGNET_LANDING_URL = "";
const SIGNET_APP_URL = "";

// Wallet-specific invite link
const DISCORD_URL = "https://discord.taostats.io";

// Docs URLs
const DOCS_URL_PREFIX = "https://docs.talisman.xyz/talisman";
const POLKADOT_VAULT_DOCS_URL = `${DOCS_URL_PREFIX}/start/importing-external-wallets/import-from-polkadot-vault`;
const PRIVACY_POLICY_URL = `${TAOSTATS_WEB_APP_URL}/extension/privacy-policy`;
const TERMS_OF_USE_URL = `${TAOSTATS_WEB_APP_URL}/extension/terms-of-use`;
const CONNECT_LEDGER_DOCS_URL = `${DOCS_URL_PREFIX}/start/importing-external-wallets/import-from-ledger`;

// Images
const UNKNOWN_TOKEN_URL = "/images/icon.png";
const UNKNOWN_NETWORK_URL = "/images/icon.png";

/* eslint-disable no-console, @typescript-eslint/no-explicit-any */


/** A function which does nothing. */
const noop = (..._data) => {};

/**
 * A simple logging utility that provides methods for logging errors, warnings, logs, and debug messages.
 * It also includes a timer utility for measuring the duration of operations.
 */
const log = {
  error: !TEST && typeof console.error === "function" ? console.error.bind(console) : noop,
  warn: !TEST && typeof console.warn === "function" ? console.warn.bind(console) : noop,
  log: !TEST && typeof console.log === "function" ? console.log.bind(console) : noop,
  debug: !TEST && typeof console.debug === "function" ? console.debug.bind(console) : noop,
  /**
   * A convenient way to create a debug timer.
   *
   * @example
   * const done = log.timer("How long does it take?")
   * await doSomething()
   * done()
   **/
  timer: label => {
    if (TEST) return () => {};
    const start = performance.now();
    return () => {
      console.debug(`${label} - ${(performance.now() - start).toFixed(2)}ms`);
    };
  }
};

const isInternalHostname = hostname => {
  return hostname === TAOSTATS_WEB_APP_DOMAIN || DEBUG && ["localhost", "127.0.0.1"].includes(hostname ?? "");
};

const isInternalUrl = url => {
  if (!url) return false;
  try {
    const hostname = new URL(url).hostname;
    return isInternalHostname(hostname);
  } catch (e) {
    return false;
  }
};

export { ASSET_DISCOVERY_API_URL, CONNECT_LEDGER_DOCS_URL, DEBUG, DISCORD_URL, DOCS_URL_PREFIX, IS_FIREFOX, POLKADOT_VAULT_DOCS_URL, PORT_CONTENT, PORT_EXTENSION, PRIVACY_POLICY_URL, SIGNET_APP_URL, SIGNET_LANDING_URL, TAOSTATS_API_URL, TAOSTATS_WEB_APP_DOMAIN, TAOSTATS_WEB_APP_STAKING_URL, TAOSTATS_WEB_APP_SWAP_URL, TAOSTATS_WEB_APP_URL, TERMS_OF_USE_URL, TEST, UNKNOWN_NETWORK_URL, UNKNOWN_TOKEN_URL, isInternalHostname, isInternalUrl, log };
