const updateTransactionStatus = async (id, status, blockNumber, confirmed) => {
  try {
    // this can be called after the tx has been overriden/replaced, check status first
    const existing = await db.transactionsV2.get(id);
    if (!existing) return false;
    if (["success", "error", "replaced"].includes(existing?.status ?? "") && !!confirmed === !!existing?.confirmed) return false;
    existing.status = status;
    existing.confirmed = !!confirmed;
    if (blockNumber !== undefined) {
      existing.blockNumber = blockNumber.toString();
    }
    await db.transactionsV2.update(id, existing);
    if (["success", "error"].includes(status)) {
      const tx = await db.transactionsV2.get(id);
      if (tx) {
        // mark pending transactions with the same nonce as replaced
        await db.transactionsV2.filter(filterIsSameNetworkAndAddressTx(tx)).filter(row => row.nonce === tx.nonce && ["pending", "unknown"].includes(row.status)).modify({
          status: "replaced"
        });

        // mark pending transactions with a lower nonce as unknown
        await db.transactionsV2.filter(filterIsSameNetworkAndAddressTx(tx)).filter(row => typeof row.nonce === "number" && typeof tx.nonce === "number" && row.nonce < tx.nonce && row.status === "pending").modify({
          status: "unknown"
        });
      }
    }
    return true;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error("updateTransactionStatus", {
      err
    });
    return false;
  }
};
const getTransactionStatus = async hash => {
  const tx = await db.transactionsV2.get(hash);
  return tx?.status ?? "unknown";
};
const updateTransactionsRestart = async () => {
  try {
    // for all successful tx, mark the pending ones with the same nonce as failed
    for (const successfulTx of await db.transactionsV2.where("status").equals("success").toArray()) {
      await db.transactionsV2.filter(filterIsSameNetworkAndAddressTx(successfulTx)).filter(row => row.nonce === successfulTx.nonce && ["pending", "unknown"].includes(row.status)).modify({
        status: "error"
      });
    }

    // mark all other pending transactions as unknown
    await db.transactionsV2.where("status").equals("pending").modify({
      status: "unknown"
    });

    // keep only the last 100 transactions
    const deleted = await db.transactionsV2.orderBy("timestamp").reverse().offset(100).delete();
    if (deleted) log.debug("[updateTransactionsRestart] Deleted %d entries", deleted);
    return true;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error("updateTransactionsRestart", {
      err
    });
    return false;
  }
};
